class MovingAvg:
    def __init__(self, window: int):
        self.window = window
        self.values = []

    def push(self, x: float) -> None:
        self.values.append(x)
        if len(self.values) > self.window:
            self.values.pop(0)

    def mean(self) -> float:
        return sum(self.values) / len(self.values)
